// Safety net after the AI (#29): the visitor always gets plain text with clickable links.
// Base URL = the address a visitor's browser uses (docker-compose LOOPCASTS_PUBLIC_URL), never host.docker.internal.
const base = ($env.LOOPCASTS_PUBLIC_URL || 'http://localhost:5180').replace(/\/+$/, '');
const help = `See [courses](${base}/Courses) or [prices](${base}/Pricing), or mail support@loopcasts.example.`;
const pages = ['Courses', 'Pricing', 'Privacy', 'Order', 'Identity/Account/Login', 'Identity/Account/ForgotPassword'];
let text = $json.output;

// No answer: the model call failed (bad key, quota, timeout); the agent continues with { error }.
if (typeof text !== 'string' || !text.trim())
  return { json: { output: `Sorry, the assistant isn't available right now. ${help}` } };

// JSON or code instead of sentences.
if (/```|^\s*[\[{]\s*["\[{]|"[\w ]+"\s*:\s*["\d\[{]/.test(text))
  return { json: { output: `Sorry, I couldn't answer that properly. ${help}` } };

text = text
  .replace(/https?:\/\/host\.docker\.internal(:\d+)?/g, base)   // n8n's own address for the site
  .replace(/\]\((\/[^)\s]*)\)/g, `](${base}$1)`)                // [text](/Pricing) → full link
  .replace(/\[([^\]]+)\]\((https?:\/\/[^)\s]+)\)/g, (link, label, url) => {   // link to another host = invented
    if (url.startsWith(`${base}/`)) return link;
    const path = url.replace(/^https?:\/\/[^/]+/, '');
    const page = pages.find(p => path.split('?')[0].toLowerCase() === `/${p}`.toLowerCase());
    return page ? `[${label}](${base}/${page}${path.includes('?') ? path.slice(path.indexOf('?')) : ''})` : label;
  })
  .replace(/(^|[\s(])\/(Courses|Pricing|Privacy|Order\?plan=[\w-]+|Identity\/Account\/[\w/]+)(?![\w/?=-])/g,
    (_, before, path) => `${before}[${path.split('?')[0].split('/').pop()}](${base}/${path})`);   // bare /Pricing → link

return { json: { output: text } };
